gLL(){return"\u0423\u043d\u0446\u0456\u0430\u043b 0229 \u2013 \u0446\u0435 \u0433\u0440\u0435\u0446\u044c\u043a\u0438\u0439 \u0443\u043d\u0446\u0456\u0430\u043b\u044c\u043d\u0438\u0439 \u0440\u0443\u043a\u043e\u043f\u0438\u0441 \u041d\u043e\u0432\u043e\u0433\u043e \u0417\u0430\u0432\u0456\u0442\u0443, \u0449\u043e \u043c\u0456\u0441\u0442\u0438\u0442\u044c \u043d\u0435\u0432\u0435\u043b\u0438\u043a\u0438\u0439 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442 \u043a\u043d\u0438\u0433\u0438 \u041e\u0431'\u044f\u0432\u043b\u0435\u043d\u043d\u044f. \u0426\u0435 \u043f\u0430\u043b\u0456\u043c\u043f\u0441\u0435\u0441\u0442, \u043d\u0438\u0436\u043d\u0456\u0439 \u0442\u0435\u043a\u0441\u0442 \u044f\u043a\u043e\u0433\u043e \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u0438\u0439 \u043a\u043e\u043f\u0442\u0441\u044c\u043a\u043e\u044e \u043c\u043e\u0432\u043e\u044e \u0456 \u043c\u0456\u0441\u0442\u0438\u0442\u044c \u043a\u0430\u043b\u0435\u043d\u0434\u0430\u0440\u043d\u0438\u0439 \u0442\u0435\u043a\u0441\u0442 \u0437\u0456 \u0441\u043f\u0438\u0441\u043a\u043e\u043c \u0454\u0433\u0438\u043f\u0435\u0442\u0441\u044c\u043a\u0438\u0445 \u043c\u0456\u0441\u044f\u0446\u0456\u0432. \u0420\u0443\u043a\u043e\u043f\u0438\u0441 \u0441\u043a\u043b\u0430\u0434\u0430\u0454\u0442\u044c\u0441\u044f \u0437 \u0434\u0432\u043e\u0445 \u043f\u0435\u0440\u0433\u0430\u043c\u0435\u043d\u0442\u043d\u0438\u0445 \u0430\u0440\u043a\u0443\u0448\u0456\u0432 \u0440\u043e\u0437\u043c\u0456\u0440\u043e\u043c \u043f\u0440\u0438\u0431\u043b\u0438\u0437\u043d\u043e 11 \xd7 23 \u0441\u043c."},
gLM(){return"\u0422\u0435\u043a\u0441\u0442 \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u0438\u0439 \u0433\u0440\u0435\u0446\u044c\u043a\u0438\u043c\u0438 \u0443\u043d\u0446\u0456\u0430\u043b\u044c\u043d\u0438\u043c\u0438 \u043b\u0456\u0442\u0435\u0440\u0430\u043c\u0438, \u0440\u043e\u0437\u0442\u0430\u0448\u043e\u0432\u0430\u043d\u0438\u0439 \u0432 \u043e\u0434\u043d\u0443 \u043a\u043e\u043b\u043e\u043d\u043a\u0443 \u043d\u0430 \u0441\u0442\u043e\u0440\u0456\u043d\u0446\u0456 \u0437 16 \u0440\u044f\u0434\u043a\u0430\u043c\u0438 \u0443 \u043a\u043e\u043b\u043e\u043d\u0446\u0456. \u0412\u0456\u043d \u0441\u043b\u0456\u0434\u0443\u0454 \u0441\u0442\u0438\u043b\u044e scriptio continua (\u0431\u0435\u0437 \u043f\u0440\u043e\u0431\u0456\u043b\u0456\u0432 \u043c\u0456\u0436 \u0441\u043b\u043e\u0432\u0430\u043c\u0438)."},
